<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('faq');$base='/admin/faq.php';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'save',20);$id=cmsInt($_POST['id']??0);if($a==='delete'&&$id){$pdo->prepare('DELETE FROM faqs WHERE id=:id')->execute([':id'=>$id]);cmsAudit('faq.delete','faqs',(string)$id);cmsAdminRedirect($base,'تم الحذف.');}if($a==='toggle'&&$id){$pdo->prepare('UPDATE faqs SET is_active=1-is_active WHERE id=:id')->execute([':id'=>$id]);cmsAudit('faq.toggle','faqs',(string)$id);cmsAdminRedirect($base,'تم تحديث الحالة.');}
$qAr=cmsStr($_POST['question_ar']??'',500);$qEn=cmsStr($_POST['question_en']??'',500);$aAr=cmsStr($_POST['answer_ar']??'');$aEn=cmsStr($_POST['answer_en']??'');$sort=cmsInt($_POST['sort_order']??0);$active=cmsBool($_POST['is_active']??0);if($qAr===''||$qEn===''||$aAr===''||$aEn==='')cmsAdminRedirect($base,'الحقول العربية والإنجليزية مطلوبة.');if($id){$s=$pdo->prepare('UPDATE faqs SET question_ar=:qa,question_en=:qe,answer_ar=:aa,answer_en=:ae,sort_order=:s,is_active=:i WHERE id=:id');$p=[':qa'=>$qAr,':qe'=>$qEn,':aa'=>$aAr,':ae'=>$aEn,':s'=>$sort,':i'=>$active,':id'=>$id];$act='faq.update';}else{$s=$pdo->prepare('INSERT INTO faqs(question_ar,question_en,answer_ar,answer_en,sort_order,is_active) VALUES(:qa,:qe,:aa,:ae,:s,:i)');$p=[':qa'=>$qAr,':qe'=>$qEn,':aa'=>$aAr,':ae'=>$aEn,':s'=>$sort,':i'=>$active];$act='faq.create';}$s->execute($p);cmsAudit($act,'faqs',(string)$id);cmsAdminRedirect($base,'تم الحفظ.');}
$edit=null;if($id=cmsInt($_GET['edit']??0)){$s=$pdo->prepare('SELECT * FROM faqs WHERE id=:id');$s->execute([':id'=>$id]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT * FROM faqs ORDER BY sort_order,id')->fetchAll();cmsAdminHead('الأسئلة الشائعة');cmsAdminSidebar('faq');cmsAdminTopbar('الأسئلة الشائعة');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><div class="split"><section class="card"><h2>الأسئلة</h2><div class="table-wrap"><table class="table"><thead><tr><th>السؤال</th><th>الحالة</th><th>الترتيب</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=cmsE($r['question_ar'])?><div class="muted"><?=cmsE($r['question_en'])?></div></td><td><span class="pill <?=$r['is_active']?'ok':'bad'?>"><?=$r['is_active']?'ظاهر':'مخفي'?></span></td><td><?=$r['sort_order']?></td><td><div class="actions"><a class="btn" href="?edit=<?=$r['id']?>">تعديل</a><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="toggle">إظهار/إخفاء</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف السؤال؟')">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2><?=$edit?'تعديل':'إضافة'?></h2><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="field"><span>السؤال AR</span><input name="question_ar" required value="<?=cmsE((string)($edit['question_ar']??''))?>"></label><label class="field"><span>Question EN</span><input name="question_en" required value="<?=cmsE((string)($edit['question_en']??''))?>"></label><label class="field"><span>الإجابة AR</span><textarea name="answer_ar" required><?=cmsE((string)($edit['answer_ar']??''))?></textarea></label><label class="field"><span>Answer EN</span><textarea name="answer_en" required><?=cmsE((string)($edit['answer_en']??''))?></textarea></label><div class="form-grid"><label class="field"><span>الترتيب</span><input type="number" name="sort_order" value="<?=intval($edit['sort_order']??0)?>"></label><label class="module-row"><span>ظاهر</span><input class="check" type="checkbox" name="is_active" value="1" <?=cmsChecked($edit['is_active']??1)?>></label></div><div class="actions" style="margin-top:16px"><button class="btn primary">حفظ</button><?php if($edit):?><a class="btn" href="<?=$base?>">إلغاء</a><?php endif;?></div></form></section></div></div><?php cmsAdminEnd();
